<?php
declare(strict_types=1);require_once __DIR__.'/config/lead_step20.php';$error=null;$success=null;$rows=[];try{$pdo=business_db();$user=security_step17_current_user($pdo);$ctx=lead_step20_context($pdo);$orgId=(int)$ctx['organization_id'];if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));lead_step20_complete_task($pdo,$orgId,(int)($_POST['task_id']??0),(int)$user['id']);$success='Follow-up completed.';}$s=$pdo->prepare("SELECT t.*,l.lead_code,l.full_name,l.mobile,u.full_name assigned_name FROM crm_lead_tasks t JOIN crm_leads l ON l.id=t.lead_id AND l.organization_id=t.organization_id LEFT JOIN system_users u ON u.id=t.assigned_user_id WHERE t.organization_id=? ORDER BY t.status='pending' DESC,(t.status='pending' AND t.due_at<NOW()) DESC,t.due_at,t.id DESC LIMIT 500");$s->execute([$orgId]);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Lead Follow-ups</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="lead_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 20 • Follow-up Queue</small></span></a><div class="os-top-actions"><a class="os-btn" href="lead_appointments.php">Appointments</a><a class="os-btn primary" href="lead_center.php">Leads</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">ACTION QUEUE</div><h1>Calls, WhatsApp, visits and email follow-ups in one due-date queue.</h1><p>Completion changes status; follow-up history is preserved.</p></section><?php if($error):?><div class="pp-alert bad"><?= lead_step20_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><?= lead_step20_h($success) ?></div><?php endif;?><section class="os-card"><div class="s10-list"><?php if(!$rows):?><div class="pp-alert">No lead follow-ups yet.</div><?php endif;?><?php foreach($rows as $r):$over=$r['status']==='pending'&&strtotime($r['due_at'])<time();?><div class="s10-row"><div><b><?= lead_step20_h(strtoupper($r['task_type']).' • '.$r['subject']) ?></b><small><a href="lead_detail.php?id=<?= (int)$r['lead_id'] ?>"><?= lead_step20_h($r['lead_code'].' • '.$r['full_name']) ?></a> • <?= lead_step20_h($r['due_at']) ?><?= $r['assigned_name']?' • '.lead_step20_h($r['assigned_name']):'' ?></small></div><div><?php if($r['status']==='pending'):?><span class="pp-badge <?= $over?'warn':'' ?>"><?= $over?'OVERDUE':'PENDING' ?></span><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="task_id" value="<?= (int)$r['id'] ?>"><button class="os-btn">Done</button></form><?php else:?><span class="pp-badge">DONE</span><?php endif;?></div></div><?php endforeach;?></div></section></main></body></html>